 return <><PageHero eyebrow={data.eyebrow} title={data.title} lead={data.lead} trail={[{label:data.title}]} navigate={navigate}/><section className="section bg-white"><div className="container-x max-w-3xl"><div className="space-y-8">{data.sections.map(([heading,body])=><section key={heading}><h2 className="display-3">{heading}</h2><p className="body-sm mt-3">{body}</p></section>)}</div><div className="mt-9 border-l-2 border-cyan bg-paper p-5 text-[.8125rem] leading-relaxed text-ink-slate"><strong className="text-navy">Please note:</strong> This page is an operational summary, not a substitute for approved legal documents or individual service terms. Contact DigiTrans if you need clarification.</div><button type="button" className="pill pill-navy pill-sm mt-7" onClick={()=>navigate('/contact')}>Ask a question<Icon name="support" size={14}/></button></div></section></>;
