function SpecialInfoPage({page,navigate,book}){
 const rider=page==='/rider-registration';
 const title=rider?'Ride with DigiTrans.':'Explore the opportunity. Understand the risk.';
 const lead=rider?'We are building a dependable local rider network. Start an application and our team will guide you through verification.':'Investment opportunities are shown only after internal review and approval. Figures marked as projected are estimates, not money earned or guaranteed.';
 const bullets=rider?['Submit identity, vehicle and guarantor information.','Review and accept the current rider agreement.','Track verification status and, after approval, assignments and earnings.']:['Review the agreement and risk disclosures before applying.','Investor identity verification is required.','Funding is confirmed through a verified payment record.','Maturity does not mean a payout has already occurred.'];
 return <><PageHero eyebrow={rider?'Ride with DigiTrans':'Investment information'} title={title} lead={lead} trail={[{label:rider?'Rider registration':'Investment information'}]} image={rider?'/images/hero-courier.jpg':'/images/vendor.jpg'} imageAlt={rider?'DigiTrans rider on a Calabar route':'DigiTrans business partner'} navigate={navigate}/><section className="section bg-white"><div className="container-x grid gap-10 lg:grid-cols-[1fr_.8fr] lg:items-start"><div><p className="eyebrow">{rider?'Onboarding':'Important information'}</p><h2 className="display-2 mt-3">{rider?'A clear route to getting started.':'Explore carefully, before applying.'}</h2><ul className="mt-7 space-y-4">{bullets.map(text=><li key={text} className="flex gap-3 text-[.9375rem] leading-6 text-ink-slate"><Icon name="check" size={17} className="mt-1 shrink-0 text-cyan"/>{text}</li>)}</ul>{!rider&&<p className="mt-6 text-[.8125rem] leading-6 text-muted">Investment involves risk. Projected returns are not guaranteed; seek independent professional advice before making a decision.</p>}</div><Card className="p-6 sm:p-8"><span className="grid h-12 w-12 place-items-center rounded-full bg-cyan/10 text-cyan"><Icon name={rider?'bike':'chart'} size={22}/></span><h3 className="mt-5 font-display text-xl font-semibold text-navy">{rider?'Ready to apply?':'Use the secure investor workspace.'}</h3><p className="mt-2 text-[.875rem] leading-6 text-ink-slate">{rider?'Create a rider account to submit your application and required documents.':'Sign in or create an investor profile to see approved opportunities and their current disclosures.'}</p><button type="button" onClick={()=>book(rider?'/register?role=rider':'/register?role=investor')} className="pill pill-navy mt-6">{rider?'Start a rider application':'Open investor portal'}<Icon name="arrow" size={14}/></button></Card></div></section></>;
}

function NotFound({navigate}){
 return <><PageHero eyebrow="Page not found" title="That route didn’t make the trip." lead="The page may have moved. Head back to the DigiTrans home page or contact our dispatch team for help." trail={[{label:'Not found'}]} navigate={navigate}/><section className="section-tight bg-white"><div className="container-x flex flex-wrap gap-3"><button type="button" onClick={()=>navigate('/')} className="pill pill-navy">Back home<Icon name="arrow" size={14}/></button><button type="button" onClick={()=>navigate('/contact')} className="pill pill-line">Contact support</button></div></section></>;
}

export default function PublicPages({page,content,navigate,onLogin,user,book}){
 const normalized=page.replace(/\/+$/,'')||'/';
 if(normalized==='/')return <HomePage content={content} navigate={navigate} book={book}/>;
 if(normalized==='/services')return <ServiceIndex navigate={navigate}/>;
 if(normalized==='/pricing')return <PricingPage navigate={navigate} book={book}/>;
 if(normalized==='/coverage')return <CoveragePage navigate={navigate}/>;
 if(normalized==='/about')return <AboutPage navigate={navigate}/>;
 if(normalized==='/contact')return <ContactPage content={content} navigate={navigate}/>;
 if(normalized==='/quote')return <QuotePage navigate={navigate} book={book}/>;
 if(normalized==='/track')return <TrackPage navigate={navigate}/>;
 if(normalized==='/payment/return')return <PaymentReturn navigate={navigate} onLogin={onLogin}/>;
 if(normalized==='/insights')return <InsightsPage navigate={navigate}/>;
 if(normalized.startsWith('/insights/')){const article=articleBySlug[normalized.slice('/insights/'.length)];return article?<ArticlePage article={article} navigate={navigate}/>:<NotFound navigate={navigate}/>;}
 if(normalized.startsWith('/services/')){const service=serviceBySlug[normalized.slice('/services/'.length)];return service?<ServiceDetail service={service} navigate={navigate} book={book}/>:<NotFound navigate={navigate}/>;}
 const legacySlug=legacyServicePaths[normalized];if(legacySlug)return <ServiceDetail service={serviceBySlug[legacySlug]} navigate={navigate} book={book}/>;
 if(normalized==='/faq')return <><PageHero eyebrow="Help centre" title="Questions we get." lead="Quick answers to common questions about delivery, tracking, Market Runs and joining the DigiTrans network." trail={[{label:'FAQ'}]} navigate={navigate}/><FaqSection items={content?.faqs?.length?content.faqs:defaultFaqs} title="How can we help?" navigate={navigate}/></>;
 if(legalPages[normalized])return <LegalPage page={normalized} navigate={navigate}/>;
 if(normalized==='/rider-registration'||normalized==='/investment-information')return <SpecialInfoPage page={normalized} navigate={navigate} book={book}/>;
 return <NotFound navigate={navigate}/>;
}
